SELECT TO_CHAR(COMMIT_SCN), TO_CHAR(SEQUENCE#), RAWTOHEX(XID), OPERATION, SEG_OWNER, TABLE_NAME, TO_CHAR(STATUS), INFO, CASE WHEN OPERATION = 'DDL' THEN SQL_REDO END, ROW_ID, CASE WHEN SEG_OWNER = 'APP' AND TABLE_NAME = 'ORDERS' THEN TO_CHAR(SYS.DBMS_LOGMNR.COLUMN_PRESENT(REDO_VALUE, 'APP.ORDERS.ID') * 2 + SYS.DBMS_LOGMNR.COLUMN_PRESENT(UNDO_VALUE, 'APP.ORDERS.ID')) WHEN SEG_OWNER = 'O''X' AND TABLE_NAME = 'T' THEN TO_CHAR(SYS.DBMS_LOGMNR.COLUMN_PRESENT(REDO_VALUE, 'O''X.T.K') * 2 + SYS.DBMS_LOGMNR.COLUMN_PRESENT(UNDO_VALUE, 'O''X.T.K')) END, CASE WHEN SEG_OWNER = 'APP' AND TABLE_NAME = 'ORDERS' THEN SYS.DBMS_LOGMNR.MINE_VALUE(REDO_VALUE, 'APP.ORDERS.ID') WHEN SEG_OWNER = 'O''X' AND TABLE_NAME = 'T' THEN SYS.DBMS_LOGMNR.MINE_VALUE(REDO_VALUE, 'O''X.T.K') END, CASE WHEN SEG_OWNER = 'APP' AND TABLE_NAME = 'ORDERS' THEN SYS.DBMS_LOGMNR.MINE_VALUE(UNDO_VALUE, 'APP.ORDERS.ID') WHEN SEG_OWNER = 'O''X' AND TABLE_NAME = 'T' THEN SYS.DBMS_LOGMNR.MINE_VALUE(UNDO_VALUE, 'O''X.T.K') END, CASE WHEN SEG_OWNER = 'APP' AND TABLE_NAME = 'ORDERS' THEN TO_CHAR(SYS.DBMS_LOGMNR.COLUMN_PRESENT(REDO_VALUE, 'APP.ORDERS.NOTE') * 2 + SYS.DBMS_LOGMNR.COLUMN_PRESENT(UNDO_VALUE, 'APP.ORDERS.NOTE')) END, CASE WHEN SEG_OWNER = 'APP' AND TABLE_NAME = 'ORDERS' THEN SYS.DBMS_LOGMNR.MINE_VALUE(REDO_VALUE, 'APP.ORDERS.NOTE') END, CASE WHEN SEG_OWNER = 'APP' AND TABLE_NAME = 'ORDERS' THEN SYS.DBMS_LOGMNR.MINE_VALUE(UNDO_VALUE, 'APP.ORDERS.NOTE') END, CASE WHEN SEG_OWNER = 'APP' AND TABLE_NAME = 'ORDERS' THEN TO_CHAR(SYS.DBMS_LOGMNR.COLUMN_PRESENT(REDO_VALUE, 'APP.ORDERS.AT') * 2 + SYS.DBMS_LOGMNR.COLUMN_PRESENT(UNDO_VALUE, 'APP.ORDERS.AT')) END, CASE WHEN SEG_OWNER = 'APP' AND TABLE_NAME = 'ORDERS' THEN SYS.DBMS_LOGMNR.MINE_VALUE(REDO_VALUE, 'APP.ORDERS.AT') END, CASE WHEN SEG_OWNER = 'APP' AND TABLE_NAME = 'ORDERS' THEN SYS.DBMS_LOGMNR.MINE_VALUE(UNDO_VALUE, 'APP.ORDERS.AT') END FROM V$LOGMNR_CONTENTS WHERE OPERATION = 'MISSING_SCN' OR (SRC_CON_NAME = 'PDB1' AND COMMIT_SCN > 42 AND OPERATION IN ('INSERT', 'UPDATE', 'DELETE', 'UNSUPPORTED', 'DDL') AND ((SEG_OWNER = 'APP' AND TABLE_NAME = 'ORDERS') OR (SEG_OWNER = 'O''X' AND TABLE_NAME = 'T')))